package ru.muz.ui

internal class SolarPath(val d: String, val fill: Boolean, val stroke: Boolean, val alpha: Float, val width: Float, val roundCap: Boolean, val roundJoin: Boolean, val evenOdd: Boolean)

internal enum class SolarStyle { LINEAR, BOLD, BROKEN, LINE_DUOTONE, BOLD_DUOTONE }

internal val SolarRotated = setOf("MoreVert")

internal val SolarAlwaysFilled = setOf("Favorite", "Pause", "PlayArrow", "SkipNext", "SkipPrevious")

internal fun solarPaths(style: SolarStyle, name: String): List<SolarPath>? = when (style) {
    SolarStyle.LINEAR -> solarLinear(name)
    SolarStyle.BOLD -> solarBold(name)
    SolarStyle.BROKEN -> solarBroken(name)
    SolarStyle.LINE_DUOTONE -> solarLineDuotone(name)
    SolarStyle.BOLD_DUOTONE -> solarBoldDuotone(name)
}

